/*
 * SIM: the REAL ui_habitat.c in this translation unit, plus read-only views of its static state for the
 * driver (`view`, `hits`, `state`). Nothing here writes to `s` or `pb`.
 */
#include "ui_habitat.c"
#include "sim.h"
#include "sim_names.inc"   // generated by build.sh from the enums above, so new views/actions name themselves

const char *sim_ui_view_name(void)
{
    unsigned v = (unsigned)s.view;
    return v < sizeof sim_view_names / sizeof *sim_view_names ? sim_view_names[v] : "?";
}
static const char *action_name(action_kind_t a)
{
    return (unsigned)a < sizeof sim_action_names / sizeof *sim_action_names ? sim_action_names[a] : "?";
}
int sim_ui_hit_count(void) { return s.hit_count; }
bool sim_ui_hit(int i, int *x, int *y, int *w, int *h, const char **action, bool *enabled)
{
    if (i < 0 || i >= s.hit_count) return false;
    *x = s.hits[i].rect.x; *y = s.hits[i].rect.y; *w = s.hits[i].rect.w; *h = s.hits[i].rect.h;
    *action = action_name(s.hits[i].action); *enabled = s.hits[i].enabled;
    return true;
}
void sim_ui_dump_hits(void)
{
    printf("HITS view=%s count=%d (from the last scene built)\n", sim_ui_view_name(), s.hit_count);
    for (int i = 0; i < s.hit_count; i++)
        printf("  [%d] %-16s value=%d rect x=%d y=%d w=%d h=%d%s\n", i, action_name(s.hits[i].action), s.hits[i].value,
               s.hits[i].rect.x, s.hits[i].rect.y, s.hits[i].rect.w, s.hits[i].rect.h, s.hits[i].enabled ? "" : " (disabled)");
}
void sim_ui_dump_state(void)
{
    printf("STATE view=%s connected=%d loading=%d count=%d active=%d offset=%d pressed=%d touch_down=%d "
           "touch_cancelled=%d dirty=%d voice_open=%d character=%s\n",
           sim_ui_view_name(), s.connected, s.loading, s.count, s.active, s.offset, s.pressed, s.touch_down,
           s.touch_cancelled, s.dirty, s.voice_open, ht_character_name(character.id));
    printf("STATE pb: seen=%d idle_min=%d count=%d title=\"%s\" time=\"%s\" rest_since=%u\n", pb.seen, pb.idle_min,
           pb.count, pb.title, pb.time, (unsigned)pb.rest_since);
    for (int i = 0; i < pb.count && i < PB_MENU_MAX; i++)
        printf("  pb.item[%d] id=%s label=\"%s\" value=\"%s\"\n", i, pb.item[i].id, pb.item[i].label, pb.item[i].value);
    for (int i = 0; i < s.count; i++)
        printf("  agent[%d] id=%s name=\"%s\" engine=%s busy=%d\n", i, s.agents[i].id, s.agents[i].name,
               s.agents[i].engine, s.agents[i].busy);
}
